import nltk

nltk.download('averaged_perceptron_tagger')

def tag_sentence(sentence):
    tokens = nltk.word_tokenize(sentence)
    tags = nltk.pos_tag(tokens)

    tagged_sentence = ''
    for token, tag in zip(tokens, tags):
        if tag.startswith('J'):
            tagged_sentence += f'<JJ>{token}</JJ>'
        elif tag.startswith('N'):
            tagged_sentence += f'<NN>{token}</NN>'
        elif tag.startswith('V'):
            tagged_sentence += f'<VB>{token}</VB>'
        elif tag.startswith('R'):
            tagged_sentence += f'<RB>{token}</RB>'
        elif tag.startswith('D'):
            tagged_sentence += f'<DT>{token}</DT>'
        elif tag == 'MD':
            tagged_sentence += f'<MD>{token}</MD>'
        elif tag == 'TO':
            tagged_sentence += f'<TO>{token}</TO>'
        elif tag == 'CC':
            tagged_sentence += f'<CC>{token}</CC>'
        elif tag == 'POS':
            tagged_sentence += f'<POS>{token}</POS>'
        elif tag == 'PRP':
            tagged_sentence += f'<PRP>{token}</PRP>'
        elif tag == 'IN':
            tagged_sentence += f'<IN>{token}</IN>'
        else:
            tagged_sentence += f'{token}'

        if ',' in token or '.' in token or ':' in token:
            tagged_sentence += ','
        else:
            tagged_sentence +=''

    return tagged_sentence.strip()

